const item = $input.item;
let text = item.json.output || "";

let hasOrder = false; let orderData = {};
let hasRegister = false; let registerData = {};
let hasQuote = false; let quoteData = {};
let hasMeetingIntent = false; 
let hasBookingConfirmation = false; let meetingData = {};

// 1. Check for ORDER tag
const orderMatch = text.match(/\|\|\|ORDER:(\{.*?\})\|\|\|/);
if (orderMatch) {
    hasOrder = true;
    try { orderData = JSON.parse(orderMatch[1]); } catch (e) { orderData = { error: "Parse failed" }; }
    text = text.replace(/\|\|\|ORDER:(\{.*?\})\|\|\|/, '').trim();
}

// 2. Check for REGISTER tag
const registerMatch = text.match(/\|\|\|REGISTER:(\{.*?\})\|\|\|/);
if (registerMatch) {
    hasRegister = true;
    try { registerData = JSON.parse(registerMatch[1]); } catch (e) { registerData = { error: "Parse failed" }; }
    text = text.replace(/\|\|\|REGISTER:(\{.*?\})\|\|\|/, '').trim();
}

// 3. Check for QUOTE tag
const quoteMatch = text.match(/\|\|\|QUOTE:(\{.*?\})\|\|\|/);
if (quoteMatch) {
    hasQuote = true;
    try { quoteData = JSON.parse(quoteMatch[1]); } catch (e) { quoteData = { error: "Parse failed" }; }
    text = text.replace(/\|\|\|QUOTE:(\{.*?\})\|\|\|/, '').trim();
}

// 4. Check for Meeting Intent (Stage 1)
if (text.includes('"hasMeetingIntent"')) {
    hasMeetingIntent = true;
    text = text.replace(/\{[^{}]*"hasMeetingIntent"[^{}]*\}/g, '').trim();
}

// 5. Check for Booking Confirmation (Stage 2)
if (text.includes('"hasBookingConfirmation"')) {
    hasBookingConfirmation = true;
    const meetingDataMatch = text.match(/"meetingData"\s*:\s*(\{[^{}]*\})/);
    if (meetingDataMatch) {
        try { meetingData = JSON.parse(meetingDataMatch[1]); } catch (e) { }
    }
    text = text.replace(/\{[^{}]*"hasBookingConfirmation"[\s\S]*?\{[^{}]*\}[\s\S]*?\}/g, '').trim();
}

// 6. Check for Cancellations
let hasCancellation = false; let targetClientName = "";
if (text.includes('"hasCancellation"')) {
    hasCancellation = true;
    const nameMatch = text.match(/"targetClientName"\s*:\s*"([^"]+)"/);
    if (nameMatch) targetClientName = nameMatch[1];
    text = text.replace(/\{[^{}]*"hasCancellation"[^{}]*\}/g, '').trim();
}

// 7. Check for Rescheduling
let hasReschedule = false; let rescheduleData = {};
if (text.includes('"hasReschedule"')) {
    hasReschedule = true;
    const reschedMatch = text.match(/\{[^{}]*"hasReschedule"[\s\S]*?\}/);
    if (reschedMatch) {
        try { rescheduleData = JSON.parse(reschedMatch[0]); } catch (e) { }
    }
    text = text.replace(/\{[^{}]*"hasReschedule"[\s\S]*?\}/g, '').trim();
}

// Final cleanup
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

return {
    json: {
        output: text,
        hasOrder: hasOrder,
        orderData: orderData,
        hasRegister: hasRegister,
        registerData: registerData,
        hasQuote: hasQuote,
        quoteData: quoteData,
        hasMeetingIntent: hasMeetingIntent,
        hasBookingConfirmation: hasBookingConfirmation,
        meetingData: meetingData,
        hasCancellation: hasCancellation,
        hasReschedule: hasReschedule,
        targetClientName: targetClientName,
        rescheduleData: rescheduleData,
        from: $('Extract Message Data').first().json.from,
        sessionId: $('Extract Message Data').first().json.sessionId
    }
};

