    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    // Convert to base64 and attach to JSON
    items[i].json.pdf_base64 = buffer.toString('base64');
  }
}

return items;

const events = $input.all();
let scheduleText = "Here are my busy times for the next 7 days:\n";

if (events.length === 0) {
  scheduleText = "I have no meetings scheduled. I am completely free.";
} else {
  events.forEach(event => {
    const start = event.json.start?.dateTime || event.json.start?.date;
    const end = event.json.end?.dateTime || event.json.end?.date;
    const title = event.json.summary || "Busy";
    scheduleText += `- ${title}: From ${start} to ${end}\n`;
  });
}

return [{ json: { busySchedule: scheduleText } }];

